@push('scripts')<script>document.querySelectorAll('[data-select-filter]').forEach((input)=>{const select=document.getElementById(input.dataset.selectFilter);if(!select)return;const original=[...select.options].map(o=>({value:o.value,text:o.text,selected:o.selected}));input.addEventListener('input',()=>{const q=input.value.toLowerCase();const current=select.value;select.innerHTML='';original.filter(o=>o.value===''||o.text.toLowerCase().includes(q)).forEach(o=>{const option=new Option(o.text,o.value,false,o.value===current);select.add(option);});});});</script>@endpush
